// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 0, type(uint256).max / 2);
        vm.assume(actor != address(c) && actor != address(this));
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        assertTrue(c.getBalance(actor) == amount);
    }
}
